 const info=panel(r.title,`<div class="stocktake-summary"><div><span>Stocktake</span><strong>#${r.id}</strong></div><div><span>Status</span><strong>${esc(runLabel(r))}</strong></div><div><span>Completed</span><strong>${r.completed??r.items.filter(i=>i.state==='counted').length} / ${r.total??r.items.length}</strong></div><div><span>Due</span><strong>${esc(r.due_date||'—')}</strong></div></div><div class="mini-actions"><a class="mini-link" href="/stocktaking/results?run=${r.id}">Results</a>${snapshot.capabilities.manage?form('display',hidden('runId',r.id)+hidden('enabled',r.display_enabled?'false':'true')+`<button class="secondary">${r.display_enabled?'End LED display':'Show stocktake LEDs'}</button>`,'display-'+r.id):''}</div><div class="stocktake-legend"><span><i class="yellow"></i>Remaining</span><span><i class="orange"></i>Counting</span><span><i class="blue"></i>Completed</span></div>`);
